const familyRules={"vector_arithmetic": "Vektorer adderas och skalas komponent för komponent; en okänd vektor fås genom att ta tillbaka kombinationen en komponent i taget.", "linear_combination_coefficients": "En kombination c₁v₁ + … + cₖvₖ är en viktad summa; koefficienterna löser systemet vars kolonner är vᵢ.", "dot_norm_angle": "u·v = Σ uᵢvᵢ; ‖v‖ = √(v·v); cos θ = u·v / (‖u‖‖v‖) för nollskilda vektorer.", "vector_orthogonality": "Vektorer är ortogonala precis när deras skalärprodukt är 0; en okänd komponent väljs så att skalärprodukten blir noll.", "vector_projection": "proj_v u = (u·v / v·v) v; resten u − proj_v u är ortogonal mot v.", "cross_product_3d": "u × v = (u₂v₃ − u₃v₂, u₃v₁ − u₁v₃, u₁v₂ − u₂v₁) är ortogonal mot båda; dess längd är parallellogrammens area.", "system_matrix_translation": "Bestäm variabelordningen; varje ekvation blir en rad, med 0 för en saknad variabel och konstanten efter strecket.", "row_operation": "Byt två rader, multiplicera en rad med ett nollskilt tal, eller addera en multipel av en rad till en annan — alltid över hela raden, även högerledet.", "echelon_pivots": "Trappstegsform: nollrader sist, varje ledande element till höger om det ovanför. RREF kräver också ledande ettor med nollor ovanför och under.", "compute_rref": "Eliminera kolonn för kolonn med exakta bråk tills varje pivåelement är 1 och är det enda nollskilda elementet i sin kolonn; RREF är entydig.", "solve_unique_system": "Radreducera [A | b]; när varje variabel har ett pivåelement, läs av lösningen och kontrollera med Ax = b.", "solve_parametric_system": "Fria variabler blir parametrar: lösningsmängden är en partikulärlösning plus varje kombination av nollrummets riktningar.", "classify_system": "Ingen lösning när rang A < rang [A | b]; annars en entydig lösning om rangen är lika med antalet variabler, annars oändligt många.", "matrix_shape_entries": "En m × n-matris har m rader och n kolonner, elementet aᵢⱼ i rad i, kolonn j, och avbildar ℝⁿ på ℝᵐ.", "matrix_arithmetic": "Matriser av samma storlek adderas och skalas element för element; matrisekvationer löses som vanliga linjära ekvationer.", "matrix_vector_product": "Ax är kombinationen x₁a₁ + … + xₙaₙ av A:s kolonner, samma sak som skalärprodukter av raderna med vektorn.", "matrix_product": "(AB)ᵢⱼ är rad i i A gånger kolonn j i B; AB finns bara när antalet kolonner i A är lika med antalet rader i B, och oftast är AB ≠ BA.", "transpose_properties": "Aᵀ byter rader mot kolonner; (AB)ᵀ = BᵀAᵀ; A är symmetrisk när Aᵀ = A och antisymmetrisk när Aᵀ = −A.", "matrix_inverse": "[[a, b], [c, d]]⁻¹ = (1/(ad − bc))[[d, −b], [−c, a]] när ad − bc ≠ 0; då ger Ax = b att x = A⁻¹b.", "lu_factorization": "Eliminera under diagonalen; varje multiplikator lᵢⱼ placeras i den undertriangulära L med ettor på diagonalen, och resultatet är U. Lös Ax = b via Ly = b och sedan Ux = y.", "transformation_geometry": "En avbildnings matris har kolonnerna T(e₁), T(e₂); att först göra S och sedan T har matrisen TS.", "determinant_compute": "det [[a, b], [c, d]] = ad − bc; determinanten av en triangulär matris är produkten av diagonalen; för 3 × 3, utveckla längs en rad eller eliminera.", "determinant_row_operations": "Ett radbyte multiplicerar det med −1, att skala en rad med c multiplicerar den med c, och att addera en multipel av en annan rad lämnar den oförändrad.", "cofactor_expansion": "Cᵢⱼ = (−1)^(i+j)Mᵢⱼ; det A är summan av elementen i en valfri rad eller kolonn gånger deras kofaktorer, så utveckla längs linjen med flest nollor.", "invertibility_equivalences": "För kvadratisk A: det A ≠ 0 ⇔ ett pivåelement i varje kolonn ⇔ RREF = I ⇔ Null(A) = {0} ⇔ inverterbar. Rektangulära matriser skiljer dessa villkor åt.", "subspace_test": "Ett delrum innehåller 0 och är slutet under addition och multiplikation med skalär; ett enda motexempel mot något av dessa räcker för att utesluta det.", "span_membership": "w ∈ span{v₁, …, vₖ} precis när Vc = w är lösbart; lösningen c ger koefficienterna.", "linear_independence": "Vektorer är oberoende när Vc = 0 bara har lösningen c = 0; varje nollskild lösning är en beroenderelation.", "basis_dimension": "En bas spänner upp rummet och är oberoende; stryk överflödiga vektorer, behåll de ursprungliga pivåkolonnerna eller lös de definierande ekvationerna.", "basis_coordinates": "Med B = [b₁ … bₙ], lös B[v]_B = v för koordinaterna, och beräkna v = B[v]_B för att återskapa vektorn.", "fundamental_subspaces": "Col(A) från de ursprungliga pivåkolonnerna, Row(A) från de nollskilda raderna i RREF, Null(A) genom att lösa Ax = 0, och Null(Aᵀ) = Col(A)⊥.", "rank_nullity": "För en m × n-matris gäller rang + nolldimension = n, radrang = kolonnrang och dim Null(Aᵀ) = m − rang.", "linearity_check": "T är linjär när T(u + v) = T(u) + T(v) och T(cu) = cT(u); konstanter, kvadrater, produkter och absolutbelopp bryter detta.", "kernel_image": "Kärnan är Null(A) och bilden är Col(A); T är injektiv när kärnan är {0} och surjektiv på ℝᵐ när rangen = m.", "matrix_of_linear_map": "Standardmatrisen har kolonnerna T(e₁), …, T(eₙ); i baserna B och C är kolonn j C-koordinatvektorn för T(bⱼ).", "map_composition": "Om S verkar först och T sedan är [T∘S] = [T][S], och storlekarna kedjas: (p × q)(q × r) = p × r.", "change_of_basis_similarity": "v = P_B[v]_B och [v]_B = P_B⁻¹v; P_(C←B) = P_C⁻¹P_B; samma avbildning i basen B är P⁻¹AP, som är similär med A, inte lika med den.", "eigenpair_check": "v ≠ 0 är en egenvektor med egenvärdet λ när Av = λv: beräkna Av och se om den är en enda multipel av v. Nollvektorn räknas aldrig.", "characteristic_polynomial": "det(λI − A) är moniskt; för 2 × 2 är det λ² − (spår)λ + det, och för en triangulär matris är det produkten av (λ − aᵢᵢ).", "find_eigenvalues": "Egenvärdena är rötterna till det(λI − A), räknade med algebraisk multiplicitet; deras summa är spåret och deras produkt det A.", "eigenspace_basis": "Egenrummet för λ är Null(A − λI); dess dimension är den geometriska multipliciteten, mellan 1 och den algebraiska multipliciteten.", "diagonalization": "A = PDP⁻¹ kräver n oberoende egenvektorer som kolonner i P, med motsvarande egenvärden på D:s diagonal i samma ordning; ett för litet egenrum gör det omöjligt.", "eigen_matrix_powers_dynamics": "Aᵏv = λᵏv för en egenvektor; dela upp x i egenvektorer för att beräkna Aᵏx; en Markovkedjas stationära tillstånd är dess egenvektor för λ = 1.", "orthogonal_complement": "W⊥ är alla vektorer ortogonala mot hela W: lös ett homogent system med W:s spännande vektorer som rader. dim W + dim W⊥ = n, Col(A)⊥ = Null(Aᵀ), Row(A)⊥ = Null(A).", "gram_schmidt": "uₖ = vₖ minus dess projektioner på u₁, …, uₖ₋₁; sedan qₖ = uₖ/‖uₖ‖. Ordningen spelar roll, och varje början av listan behåller sitt hölje.", "qr_factorization": "Gram–Schmidt på A:s kolonner ger Q; R = QᵀA är övertriangulär, och krav på positiv diagonal gör faktoriseringen entydig.", "least_squares": "x̂ löser AᵀAx̂ = Aᵀb, vilket gör residualen b − Ax̂ ortogonal mot Col(A); en linjeanpassning använder A = [x 1].", "projection_matrix": "På en linje: P = aaᵀ/(aᵀa); på Col(A): P = A(AᵀA)⁻¹Aᵀ. Varje ortogonal projektion uppfyller P² = P och Pᵀ = P.", "symmetric_spectral": "En reell symmetrisk A = QΛQᵀ med ortogonal Q: egenvektorer för olika egenvärden är ortogonala, och egenvärdenas tecken ger definitheten.", "quadratic_form": "q(x) = xᵀAx med symmetrisk A: kvadrattermernas koefficienter på diagonalen, halva varje korstermskoefficient utanför. I huvudaxlar är q = Σ λᵢyᵢ².", "singular_value_decomposition": "A = UΣVᵀ med ortogonala U, V och sorterad Σ ≥ 0; σᵢ är kvadratrötterna ur egenvärdena till AᵀA, antalet nollskilda är rangen, och σ₁ är normen."};
